                const _warn = g.warn ? `<div style="font-size:10px;color:${C.amber};background:${C.amber}14;border:1px solid ${C.amber}44;border-radius:6px;padding:6px 10px;margin:-2px 0 8px;line-height:1.5">⚠ ${esc(g.warn)}</div>` : '';
