        for (let k = 0; k < K; k++) { const ax = [], ay = [], al = []; for (let i = 0; i < n; i++) if (i % K !== k) { ax.push(xs[i]); ay.push(ys[i]); al.push(ld[i]); } if (ax.length < 6) { agree++; continue; } const d = tribePartial(ax, ay, al); if ((d >= 0) === (dec >= 0) && Math.abs(d) > 1e-6) agree++; }
