        const W = 820, H = 540, pad = 24, X = x => pad + (x - xmin) / (xmax - xmin || 1) * (W - 2 * pad), Y = y => pad + (1 - (y - ymin) / (ymax - ymin || 1)) * (H - 2 * pad);
