        const legend = Object.keys(TRIBE_FAMCOL).map((f, i) => `<g transform="translate(${pad + i * 130},${H - 8})"><circle cx="5" cy="-4" r="5" fill="${TRIBE_FAMCOL[f]}"/><text x="15" y="0" fill="${C.dim}" font-size="10">${f}</text></g>`).join('');
