            const t = JSON.parse(window.localStorage.getItem(RAWTRACE_KEY) || 'null');
            if (!t || !t.steps || !t.steps.length) return;
            window.localStorage.removeItem(RAWTRACE_KEY);
            const last = t.steps[t.steps.length - 1];
