            context.save(); context.translate(11, (top + H - bottom) / 2); context.rotate(-Math.PI / 2); context.fillText(`actual public views (${st.savedChannelAtlasScale === 'raw' ? 'raw' : 'log spacing'})`, 0, 0); context.restore();
